//! Parameter registry accessor (spec/DOCS-parameters.md). The generated
//! `params.json` is compiled in; nothing in `src/` holds a tunable literal.
//! `Params::reload_from_disk` is the native F5 path (mirrors Godot's
//! `Params.load_registry`).
use bevy::prelude::Resource;
use serde::Deserialize;
use std::collections::BTreeMap;

/// The registry compiled into the binary (also the web source of truth).
const EMBEDDED: &str = include_str!("../params.json");

/// One registry entry as generated by `tools/gen_params.py`.
#[derive(Deserialize, Clone, Debug)]
pub struct Entry {
    /// Current value (shipped default until a slider moves it).
    pub value: f32,
    /// Debug slider lower bound.
    pub min: f32,
    /// Debug slider upper bound.
    pub max: f32,
    /// Debug slider increment.
    pub step: f32,
    /// Display unit, e.g. `px/s`.
    pub unit: String,
    /// One-line description, shown by the debug overlay.
    pub desc: String,
}

/// Registry loaded at startup; mutable so a debug overlay can tweak live.
/// Keys iterate in alphabetical order (stable overlay row order).
#[derive(Resource, Clone, Debug)]
pub struct Params {
    entries: BTreeMap<String, Entry>,
    hash: String,
}

impl Params {
    /// Parse the embedded registry.
    ///
    /// # Panics
    /// If `params.json` is malformed; that is a build error, not a runtime one.
    #[must_use]
    pub fn load() -> Self {
        Self::parse(EMBEDDED).expect("embedded params.json parses")
    }

    /// Parse registry text, skipping `_`-prefixed metadata keys.
    ///
    /// # Errors
    /// On JSON that is not an object of well-formed entries.
    pub fn parse(text: &str) -> Result<Self, String> {
        let raw: BTreeMap<String, serde_json::Value> =
            serde_json::from_str(text).map_err(|e| format!("params: {e}"))?;
        let mut entries = BTreeMap::new();
        for (key, value) in raw.into_iter().filter(|(k, _)| !k.starts_with('_')) {
            let entry = serde_json::from_value(value).map_err(|e| format!("params {key}: {e}"))?;
            entries.insert(key, entry);
        }
        Ok(Self { entries, hash: fnv1a_hex(text) })
    }

    /// F5: re-read `params.json` from the source tree (native). Falls back to
    /// the embedded copy where no file exists (installed binary, web).
    ///
    /// # Errors
    /// If the file exists but does not parse; the old registry is kept.
    pub fn reload_from_disk(&mut self) -> Result<(), String> {
        let path = concat!(env!("CARGO_MANIFEST_DIR"), "/params.json");
        let text = std::fs::read_to_string(path).unwrap_or_else(|_| EMBEDDED.to_owned());
        *self = Self::parse(&text)?;
        Ok(())
    }

    /// Current value of a tunable.
    ///
    /// # Panics
    /// On an unknown key: a typo is a bug, not a fallback case.
    #[must_use]
    pub fn get(&self, key: &str) -> f32 {
        self.entry(key).value
    }

    /// Full entry (bounds, unit, description) for the generated overlay.
    ///
    /// # Panics
    /// On an unknown key.
    #[must_use]
    pub fn entry(&self, key: &str) -> &Entry {
        self.entries.get(key).unwrap_or_else(|| panic!("unknown param: {key}"))
    }

    /// Live tweak from the debug overlay, clamped to the entry's bounds.
    ///
    /// # Panics
    /// On an unknown key.
    pub fn set(&mut self, key: &str, value: f32) {
        let e = self.entries.get_mut(key).unwrap_or_else(|| panic!("unknown param: {key}"));
        e.value = value.clamp(e.min, e.max);
    }

    /// All tunable keys, for generating the debug overlay.
    pub fn keys(&self) -> impl Iterator<Item = &str> {
        self.entries.keys().map(String::as_str)
    }

    /// Hash of the registry file text; tags saves and snapshots.
    #[must_use]
    pub fn registry_hash(&self) -> &str {
        &self.hash
    }
}

/// 64-bit FNV-1a as hex: a tag, not a security hash (no extra dependency).
fn fnv1a_hex(text: &str) -> String {
    let hash = text
        .bytes()
        .fold(0xcbf2_9ce4_8422_2325_u64, |h, b| (h ^ u64::from(b)).wrapping_mul(0x0100_0000_01b3));
    format!("{hash:016x}")
}
